import XCTest
import CryptoKit
import GlookoKit

final class SyntheticIBFTests: XCTestCase {
    /// Hashes are from independently generated Python payloads submitted to Glooko,
    /// with persistent, reconciled pump records. They are not generated by this codec.
    func testMatchesAcceptedDeviceFiles() throws {
        let fixtures: [(SyntheticIBF.Scenario, String, UInt32, Int, String)] = [
            (.smoke, "2026-10-25", 999000104, 4180,
             "fcce9c0c56f9840e64f3d0fa92082634f90b7d35fce8cad331172e9f405f0fd0"),
            (.closedDay, "2026-10-24", 999000107, 4536,
             "3b7a24b8ca4ec33c9a876793b5d5fa77974981a9b0e4348061a9b97f66decbff"),
        ]
        for (scenario, day, serial, count, expectedHash) in fixtures {
            let file = try SyntheticIBF.encode(scenario: scenario, localDay: day, serial: serial)
            let hash = SHA256.hash(data: file).map { String(format: "%02x", $0) }.joined()
            XCTAssertEqual(file.count, count, day)
            XCTAssertEqual(hash, expectedHash, day)
        }
    }
}
